/**
 * GUI static assets.
 *
 * The browser bundle lives in plain files under `web/` so it can be edited and
 * syntax-highlighted like any other front-end code. Two runtimes must work:
 *
 *   node bin/myclaude.js --gui   read the files from disk next to this module
 *   dist/myclaude.exe --gui      a compiled binary has no sibling files, so the
 *                                same sources are embedded into the bundle at
 *                                build time (scripts/bundle-gui.mjs writes the
 *                                EMBEDDED block below before compiling)
 *
 * The loader therefore prefers the filesystem and falls back to the embedded
 * copy. Returning disk content first also means `node` users get live edits on
 * refresh without rebuilding anything.
 */
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

/** @returns {string|null} file contents, or null when running from a binary. */
function readAsset(relative) {
  try {
    return readFileSync(fileURLToPath(new URL(relative, import.meta.url)), "utf8");
  } catch {
    return null;
  }
}

let cached = null;

/**
 * @typedef {{ page: string, styles: string, markdown: string, app: string }} GuiAssets
 * @returns {GuiAssets}
 */
export function loadGuiAssets() {
  if (cached) return cached;
  cached = {
    page: readAsset("web/page.html") ?? EMBEDDED.page,
    styles: readAsset("web/css/styles.css") ?? EMBEDDED.styles,
    markdown: readAsset("web/js/markdown.js") ?? EMBEDDED.markdown,
    usageChart: readAsset("web/js/usage-chart.js") ?? EMBEDDED.usageChart ?? "",
    app: readAsset("web/js/app.js") ?? EMBEDDED.app,
  };
  if (!cached.page || !cached.styles || !cached.app) {
    throw new Error(
      "GUI assets are missing: src/ui/web/ not found next to the module and no embedded copy present. " +
        "Run \"npm run build:embed\" before compiling a standalone binary."
    );
  }
  return cached;
}

/** True when the running process serves the on-disk sources (not a compiled binary). */
export function assetsFromDisk() {
  return readAsset("web/page.html") !== null;
}

